Here's a simple Python script using Flask to build a screensharing app. This script will start a screen sharing session and return a link that can be shared with others.

Note: This is a very basic implementation and does not include any security or error handling. It also uses a very simple method of generating the session link (just a randomly generated string).

```Python
from flask import Flask, request, jsonify
from flask_socketio import SocketIO, emit
import random
import string
import os
import imp

app = Flask(__name__)
app.config['SECRET_KEY'] = 'mysecretkey'
socketio = SocketIO(app)

# Dictionary to store active sessions
sessions = {}

@app.route('/start', methods=['POST'])
def start_session():
    url = request.form.get('url')
    if url in sessions:
        return jsonify({'error': 'Session already started'})
    session_id = ''.join(random.choices(string.ascii_letters + string.digits, k=12))
    sessions[url] = session_id
    return jsonify({'session_id': session_id})

@app.route('/join', methods=['POST'])
def join_session():
    session_id = request.form.get('session_id')
    url = None
    for k, v in sessions.items():
        if v == session_id:
            url = k
            break
    if url is None:
        return jsonify({'error': 'Invalid session ID'})
    return jsonify({'url': url})

if __name__ == '__main__':
    socketio.run(app)
```

