const G = 9.81; // gravitational acceleration (m/s^2)
const L = 100; // pendulum length (in pixels)
const CANVAS_WIDTH = 400;
const CANVAS_HEIGHT = 400;
const FRAME_RATE = 60; // frames per second

// Initialize canvas and context
const canvas = document.getElementById('pendulum-canvas');
const ctx = canvas.getContext('2d');

// Initialize pendulum state
let angle = 0; // initial angle (in radians)
let velocity = 0; // initial velocity (in m/s)
let released = false; // has the pendulum been released?

// Animation frame loop
function animate() {
  if (!released) {
    requestAnimationFrame(animate);
    return;
  }

  // Update pendulum state
  velocity += -G * Math.sin(angle) / L;
  angle += velocity;

  // Draw pendulum
  ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, L, -Math.PI / 2, -angle - Math.PI / 2);
  ctx.stroke();

  // Check if pendulum has stopped
  if (Math.abs(velocity) < 0.01) {
    released = false;
  }
}

// Event listeners
document.getElementById('release-button').addEventListener('click', () => {
  released = true;
  angle = Math.PI / 180 * parseFloat(document.getElementById('initial-angle').value);
