```jsx
import Head from 'next/head';
import Nav from '../components/Nav';

function MyApp({ Component, pageProps, error }) {
  if (error) {
    // If it's a 404 error, don't render the navbar
    return (
      <div>
        <Head>
          <title>404 Not Found</title>
        </Head>
        <Component {...pageProps} />
      </div>
    );
  }

  const showNavbar = !error && !isExcludedPath(location.pathname);

  return (
    <div>
      {showNavbar && <Nav />}
      <Head>
        <title>My App</title>
      </Head>
      <Component {...pageProps} />
    </div>
  );
}

MyApp.getInitialProps = async () => {
  // Get the location pathname
  const location = useRouter().pathname;

  return {
    // Pass the location pathname as a prop
    pathname: location,
  };
};

function isExcludedPath(pathname) {
  // Define an array of excluded paths
  const excludedPaths = ['/login', '/register'];

  return excludedPaths.includes(pathname);
}

export default MyApp;
